-- Synthetic data only. Transaction rolled back after each entire scenario.
BEGIN;
SET LOCAL ROLE authenticated;
SELECT community_test.actor(1);
SELECT public.save_server_community(community_test.id('a'),community_test.payload('a'),0);
INSERT INTO public.roles(id,server_id,name,permissions) VALUES
 ('c2000000-0000-0000-0000-000000000005',community_test.id('a'),'Coop','{"view_channel":true}');
CREATE TEMP TABLE cfg AS SELECT public.get_community_experience(community_test.id('a'))->'experience' AS v;
-- No raw configuration column grant, including for owners.
SELECT community_test.denied('SELECT experience FROM public.server_community_settings','42501');

UPDATE cfg SET v=jsonb_set(jsonb_set(jsonb_set(jsonb_set(v,'{rules_required}','true'),'{roles_enabled}','true'),'{role_ids}','["c2000000-0000-0000-0000-000000000005"]'),'{featured_channels}',jsonb_build_array(community_test.id('a-welcome')));
SELECT community_test.assert(public.save_community_experience(community_test.id('a'),(SELECT v FROM cfg),1)=2,'owner saves experience');
SELECT community_test.assert(public.save_community_experience(community_test.id('a'),(SELECT v FROM cfg),2)=2,'same revision no-op');
SELECT community_test.denied($sql$SELECT public.save_community_experience(community_test.id('a'),(SELECT v FROM cfg),1)$sql$,'40001','community_revision_conflict');
SELECT community_test.denied($sql$SELECT public.save_community_experience(community_test.id('a'),(SELECT v FROM cfg)||'{"surprise":true}',2)$sql$,'22023');
SELECT community_test.denied($sql$SELECT public.save_community_experience(community_test.id('a'),jsonb_set((SELECT v FROM cfg),'{role_ids}',jsonb_build_array(community_test.id('a-member-role'))),2)$sql$,'22023','community_role_ineligible');
SELECT community_test.denied($sql$SELECT public.save_community_experience(community_test.id('a'),jsonb_set((SELECT v FROM cfg),'{role_ids}','["c2000000-0000-0000-0000-000000000002"]'),2)$sql$,'22023');
SELECT community_test.denied($sql$SELECT public.save_community_experience(community_test.id('a'),jsonb_set((SELECT v FROM cfg),'{featured_channels}',jsonb_build_array(community_test.id('b-welcome'))),2)$sql$,'22023','community_invalid_channel');
SELECT community_test.denied($sql$SELECT public.save_community_experience(community_test.id('a'),jsonb_set((SELECT v FROM cfg),'{banner_url}','"javascript:alert(1)"'),2)$sql$,'22023');
SELECT community_test.denied($sql$SELECT public.save_community_experience(community_test.id('a'),jsonb_set((SELECT v FROM cfg),'{banner_url}','"https://user:password@example.test/image.png"'),2)$sql$,'22023');
SELECT community_test.denied($sql$SELECT public.save_community_experience(community_test.id('a'),jsonb_set((SELECT v FROM cfg),'{notices}','[{"id":"c3000000-0000-0000-0000-000000000009","title":"","body":"bad"}]'),2)$sql$,'22023');
SELECT community_test.assert(NOT(public.get_server_community(community_test.id('a'))->'settings' ? 'experience'),'foundation projection remains private');
SELECT public.set_community_role_permission(community_test.id('a'),community_test.id('delegate-role'),true);
SELECT community_test.actor(2);
SELECT community_test.assert(public.save_community_experience(community_test.id('a'),(SELECT v FROM cfg),2)=2,'delegate can configure');
SELECT community_test.actor(3);
SELECT community_test.denied($sql$SELECT public.save_community_experience(community_test.id('a'),(SELECT v FROM cfg),2)$sql$,'42501');
SELECT community_test.actor(5);
SELECT community_test.assert(public.community_text_allowed(community_test.id('a')),'existing member is preserved');
SELECT community_test.denied($sql$INSERT INTO public.community_member_onboarding(member_id,server_id) SELECT id,server_id FROM public.server_members WHERE user_id=auth.uid()$sql$,'42501');
SELECT community_test.actor(8);
SELECT community_test.assert(public.get_community_experience(community_test.id('b')) IS NULL,'ordinary server no home or onboarding');
SELECT community_test.denied($sql$SELECT public.get_community_experience(community_test.id('a'))$sql$,'42501');
SELECT community_test.actor(7);
SELECT public.join_server_by_invite(community_test.invite('a'));
-- Transaction timestamps predate config writes; emulate the later real HTTP join timestamp.
RESET ROLE;
ALTER TABLE public.server_members DISABLE TRIGGER security_identity;
UPDATE public.server_members SET joined_at=clock_timestamp() WHERE user_id=community_test.user_id(7) AND server_id=community_test.id('a');
ALTER TABLE public.server_members ENABLE TRIGGER security_identity;

SET LOCAL ROLE authenticated;
SELECT community_test.actor(7);
SELECT community_test.assert((public.get_community_experience(community_test.id('a'))->>'screened')::boolean,'new member screened');
SELECT community_test.assert(NOT public.community_text_allowed(community_test.id('a')),'new member blocked until acceptance');
SELECT community_test.denied($sql$INSERT INTO public.messages(channel_id,author_id,content) VALUES(community_test.id('a-welcome'),auth.uid(),'must not send')$sql$,'42501');
SELECT community_test.denied($sql$INSERT INTO public.message_reactions(message_id,user_id,emoji) SELECT id,auth.uid(),'before' FROM public.messages WHERE channel_id=community_test.id('a-welcome') LIMIT 1$sql$,'42501');
SELECT community_test.denied($sql$SELECT public.save_community_onboarding(community_test.id('a'),2,1,false,'{}','{}',true)$sql$,'42501','community_rules_required');
SELECT public.save_community_onboarding(community_test.id('a'),2,1,false,ARRAY['coop'],ARRAY['c2000000-0000-0000-0000-000000000005']::uuid[],false);
SELECT community_test.assert((SELECT completed_revision IS NULL AND interests=ARRAY['coop'] FROM public.community_member_onboarding),'interrupted draft is persisted');
SELECT community_test.assert(NOT EXISTS(SELECT FROM public.member_roles mr JOIN public.server_members m ON m.id=mr.member_id WHERE m.user_id=auth.uid() AND mr.role_id='c2000000-0000-0000-0000-000000000005'),'draft never grants roles');
SELECT community_test.denied($sql$SELECT public.save_community_onboarding(community_test.id('a'),2,1,true,'{}',ARRAY['c2000000-0000-0000-0000-000000000002']::uuid[],true)$sql$,'22023');
SELECT public.save_community_onboarding(community_test.id('a'),2,1,true,ARRAY['coop'],ARRAY['c2000000-0000-0000-0000-000000000005']::uuid[],true);
SELECT public.save_community_onboarding(community_test.id('a'),2,1,true,ARRAY['coop'],ARRAY['c2000000-0000-0000-0000-000000000005']::uuid[],true);
SELECT community_test.assert(public.community_text_allowed(community_test.id('a')),'accepted member may send');
INSERT INTO public.messages(channel_id,author_id,content) VALUES(community_test.id('a-welcome'),auth.uid(),'Message after acceptance');
SELECT community_test.assert((SELECT count(*)=1 FROM public.member_roles mr JOIN public.server_members m ON m.id=mr.member_id WHERE m.user_id=auth.uid() AND mr.role_id='c2000000-0000-0000-0000-000000000005'),'safe role assigned exactly once');
SELECT community_test.actor(5);
SELECT community_test.assert((SELECT count(*)=0 FROM public.community_member_onboarding),'other members cannot read personal onboarding');
SELECT community_test.actor(1);
SELECT public.save_server_community(community_test.id('a'),jsonb_set(community_test.payload('a'),'{rules,0,text}','"Regras atualizadas."'),1);
SELECT community_test.actor(7);
SELECT community_test.assert(NOT public.community_text_allowed(community_test.id('a')),'new rule revision requires renewed acceptance');
WITH attempted AS (UPDATE public.messages SET content='must not update' WHERE author_id=auth.uid() RETURNING id) SELECT community_test.assert((SELECT count(*)=0 FROM attempted),'pending revision cannot edit messages');
SELECT community_test.assert((SELECT rules->0->>'text'='Respeite os participantes.' FROM public.community_rule_revisions WHERE server_id=community_test.id('a') AND revision=1),'accepted snapshot immutable');
SELECT community_test.denied($sql$SELECT public.save_community_onboarding(community_test.id('a'),2,1,true,'{}','{}',true)$sql$,'40001');
SELECT community_test.actor(1);
UPDATE public.roles SET permissions='{"manage_members":true}' WHERE id='c2000000-0000-0000-0000-000000000005';
SELECT community_test.actor(7);
SELECT community_test.assert((public.get_community_experience(community_test.id('a'))->'experience'->'role_ids')='[]','unsafe edited role disappears');
SELECT community_test.denied($sql$SELECT public.save_community_onboarding(community_test.id('a'),2,2,true,'{}',ARRAY['c2000000-0000-0000-0000-000000000005']::uuid[],true)$sql$,'22023');
SELECT public.save_community_onboarding(community_test.id('a'),2,2,true,'{}','{}',true);
SELECT community_test.actor(1);
UPDATE cfg SET v=v||'{"home_enabled":false,"rules_enabled":false,"rules_required":false,"welcome_enabled":false,"interests_enabled":false,"channels_enabled":false,"roles_enabled":false,"role_ids":[]}';
SELECT public.save_community_experience(community_test.id('a'),(SELECT v FROM cfg),2);
SELECT community_test.actor(7);
SELECT community_test.assert(NOT (public.get_community_experience(community_test.id('a'))->'experience'->>'home_enabled')::boolean,'home independently disabled');
SELECT public.save_community_onboarding(community_test.id('a'),3,2,false,'{}','{}',true);
SELECT community_test.denied($sql$SELECT public.save_community_onboarding(community_test.id('a'),3,2,false,ARRAY['coop'],'{}',true)$sql$,'22023');
SELECT community_test.actor(1);
UPDATE cfg SET v=v||'{"rules_enabled":true,"rules_required":true}';
SELECT public.save_community_experience(community_test.id('a'),(SELECT v FROM cfg),3);
SELECT public.disable_server_community(community_test.id('a'),2);
SELECT community_test.actor(7);
SELECT community_test.assert(public.get_community_experience(community_test.id('a')) IS NULL AND public.community_text_allowed(community_test.id('a')),'deactivation restores ordinary text');
SELECT community_test.actor(8);
SELECT public.join_server_by_invite(community_test.invite('a'));
RESET ROLE;
ALTER TABLE public.server_members DISABLE TRIGGER security_identity;
UPDATE public.server_members SET joined_at=clock_timestamp() WHERE user_id=community_test.user_id(8) AND server_id=community_test.id('a');
ALTER TABLE public.server_members ENABLE TRIGGER security_identity;
SET LOCAL ROLE authenticated;
SELECT community_test.actor(1);
SELECT public.save_server_community(community_test.id('a'),community_test.payload('a'),3);
SELECT community_test.actor(8);
SELECT community_test.assert(public.community_text_allowed(community_test.id('a')) AND NOT (public.get_community_experience(community_test.id('a'))->>'screened')::boolean,'reactivation preserves members admitted while disabled');
SET LOCAL ROLE anon;
SELECT community_test.denied($sql$SELECT public.get_community_experience(community_test.id('a'))$sql$,'42501');
SELECT community_test.denied('SELECT * FROM public.community_member_onboarding','42501');
RESET ROLE;
ROLLBACK;
SELECT 'PASS: experience permissions, onboarding drafts/completion, safe roles, screening, revisions and privacy';
